using System;

struct PointS { public int X; }
class PointC { public int X; }

class Program
{
    static void Main()
    {
        PointS s1 = new PointS { X = 1 };
        PointS s2 = s1;   // copies the data
        s2.X = 99;
        Console.WriteLine(s1.X); // 1

        PointC c1 = new PointC { X = 1 };
        PointC c2 = c1;   // copies the reference
        c2.X = 99;
        Console.WriteLine(c1.X); // 99

        int n = 10;
        object boxed = n; // boxing
        n = 20;
        Console.WriteLine(boxed); // 10
        int back = (int)boxed;    // unboxing
        Console.WriteLine(back + n); // 30
    }
}

