using System;
using System.Collections.Generic;
using System.Globalization;

class Program
{
    static void Main()
    {
        string[] tokens = Console.In.ReadToEnd().Split(new char[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
        var readings = new List<int?>();
        foreach (string t in tokens)
        {
            int v;
            readings.Add(int.TryParse(t, out v) ? v : (int?)null);
        }

        int valid = 0, missing = 0;
        long sum = 0;
        int? max = null;
        int? last = null;
        var filled = new List<string>();
        foreach (int? r in readings)
        {
            if (r.HasValue)
            {
                valid++;
                sum += r.Value;
                if (!max.HasValue || r.Value > max.Value) max = r;
                last = r;
            }
            else
            {
                missing++;
            }
            int f = r ?? last ?? 0;
            filled.Add(f.ToString(CultureInfo.InvariantCulture));
        }

        Console.WriteLine("Valid: " + valid);
        Console.WriteLine("Missing: " + missing);
        Console.WriteLine("Sum: " + sum);
        Console.WriteLine("Max: " + (max.HasValue ? max.Value.ToString(CultureInfo.InvariantCulture) : "n/a"));
        Console.WriteLine("Average: " + (valid == 0 ? "n/a" : ((double)sum / valid).ToString("F2", CultureInfo.InvariantCulture)));
        Console.WriteLine("Filled: " + string.Join(" ", filled));
    }
}

